CREATE TABLE gateway_audit(id BIGINT NOT NULL AUTO_INCREMENT,request_id VARCHAR(80) NOT NULL,model VARCHAR(120) NOT NULL,decision VARCHAR(30) NOT NULL,input_hash VARCHAR(128) NOT NULL,summary VARCHAR(500) NOT NULL,created_by VARCHAR(80) NOT NULL,created_at TIMESTAMP(6) NOT NULL,PRIMARY KEY(id),CONSTRAINT uk_gateway_request UNIQUE(request_id));CREATE INDEX idx_gateway_created ON gateway_audit(created_at);
